import json, pathlib, subprocess, hashlib
# provenance (same vLLM procs served both runs)
pids=subprocess.run(['pgrep','-f','vllm.entrypoints'],capture_output=True,text=True).stdout.split()
cmdlines={}
for p in pids:
    try:
        c=pathlib.Path(f'/proc/{p}/cmdline').read_bytes().replace(b'\0',b' ').decode('utf-8','replace')
        port=[w for w in c.split() if '--port' in w] or ['?']
        cmdlines[p]=c
    except: pass
nginx_conf='/etc/nginx/conf.d/vllm_lb.conf'
try: nginx_sha=hashlib.sha256(open(nginx_conf,'rb').read()).hexdigest()
except: nginx_sha='unreadable'
sweep_out=pathlib.Path('/tmp/formal_sweep.out').read_text('utf-8','replace') if pathlib.Path('/tmp/formal_sweep.out').exists() else ''
strict_lines=[l for l in sweep_out.splitlines() if '[ramp][preflight]' in l]
prov={'vllm_cmdlines':cmdlines,'strict_preflight_output':strict_lines,'nginx_conf_path':nginx_conf,'nginx_conf_sha256':nginx_sha,'note':'same 2 vLLM procs (8000@GPU0,8001@GPU1) served both lb_rr and scale runs; dtype auto; tensor_parallel=1 (no --tensor-parallel-size); gpu_memory_utilization=0.90; max-model-len 8192; max-num-seqs 256; max-num-batched-tokens 8192; prefix-caching ON'}
for d in ['experiments/results/multicard_lbrr_scale_ramp_formal_20260806','experiments/results/multicard_scale_ramp_formal_20260806']:
    pathlib.Path(d,'run_provenance.json').write_text(json.dumps(prov,indent=2,ensure_ascii=False),'utf-8')
print('provenance written; nginx_sha',nginx_sha[:12],'vllm_pids',list(cmdlines))
